-- content.db: study content generated by scripts/content/build.ts.
-- Rebuilt from scratch on every run; never holds user progress.
-- JSON columns hold arrays/objects as text.

CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE sources (
  name    TEXT PRIMARY KEY,
  version TEXT NOT NULL,
  license TEXT NOT NULL,
  url     TEXT NOT NULL,
  credit  TEXT NOT NULL
);

-- KRADFILE components. glyph is KRADFILE's character (may be a stand-in like 化);
-- display is what to show (⺅).
CREATE TABLE components (
  glyph        TEXT PRIMARY KEY,
  display      TEXT NOT NULL,
  name         TEXT NOT NULL,
  stroke_count INTEGER NOT NULL
);

CREATE TABLE kanji (
  character    TEXT PRIMARY KEY,
  meanings     TEXT NOT NULL,  -- JSON string[]
  on_readings  TEXT NOT NULL,  -- JSON string[], katakana
  kun_readings TEXT NOT NULL,  -- JSON string[], "." marks okurigana: た.べる
  nanori       TEXT NOT NULL,  -- JSON string[], name readings
  grade        INTEGER,        -- 1–6 school grade, 8 = rest of jōyō, 9–10 = jinmeiyō
  jlpt_old     INTEGER,        -- pre-2010 JLPT level, 4 (easiest) … 1
  freq_rank    INTEGER,        -- 1 = most frequent
  stroke_count INTEGER NOT NULL,
  stroke_svg   TEXT            -- KanjiVG SVG, NULL if missing
);

CREATE TABLE kanji_components (
  kanji     TEXT NOT NULL REFERENCES kanji(character),
  component TEXT NOT NULL REFERENCES components(glyph),
  PRIMARY KEY (kanji, component)
);

-- Common JMdict words. id is the JMdict entry number, stable across releases.
CREATE TABLE words (
  id            TEXT PRIMARY KEY,
  written       TEXT NOT NULL,   -- main form (kanji form, or kana for kana-only words)
  reading       TEXT NOT NULL,   -- kana reading of the main form
  other_forms   TEXT NOT NULL,   -- JSON string[]
  senses        TEXT NOT NULL,   -- JSON {pos: string[], glosses: string[], misc: string[], info: string[]}[]
  priority      INTEGER NOT NULL, -- lower = more frequent (see priority.ts)
  usually_kana  INTEGER NOT NULL  -- 1 if normally written in kana
);

CREATE TABLE word_kanji (
  word_id TEXT NOT NULL REFERENCES words(id),
  kanji   TEXT NOT NULL REFERENCES kanji(character),
  PRIMARY KEY (word_id, kanji)
);
CREATE INDEX word_kanji_by_kanji ON word_kanji(kanji);

-- Tatoeba example sentences, linked to words by JMdict.
CREATE TABLE sentences (
  id       TEXT PRIMARY KEY,  -- Tatoeba sentence id
  japanese TEXT NOT NULL,
  english  TEXT NOT NULL
);

CREATE TABLE word_sentences (
  word_id     TEXT NOT NULL REFERENCES words(id),
  sentence_id TEXT NOT NULL REFERENCES sentences(id),
  form        TEXT NOT NULL,  -- how the word appears in the sentence
  PRIMARY KEY (word_id, sentence_id)
);
CREATE INDEX word_sentences_by_sentence ON word_sentences(sentence_id);

-- Hiragana and katakana (scripts/content/kana.ts).
CREATE TABLE kana (
  character   TEXT PRIMARY KEY,
  romaji      TEXT NOT NULL,   -- Hepburn
  accept      TEXT NOT NULL,   -- JSON string[]: extra accepted answers (を → "o")
  script      TEXT NOT NULL CHECK (script IN ('hiragana', 'katakana')),
  grp         TEXT NOT NULL CHECK (grp IN ('basic', 'dakuten', 'combo', 'extended')),
  counterpart TEXT,            -- same sound in the other script
  stroke_svg  TEXT             -- KanjiVG SVG, single characters only
);

-- Default learning order. item_key is "kana:<char>", "component:<glyph>",
-- "kanji:<char>" or "word:<id>"; user progress refers to items by this key.
-- Each track (kana, main) has its own lesson queue and daily limit.
CREATE TABLE path (
  position INTEGER PRIMARY KEY,
  item_key TEXT NOT NULL UNIQUE,
  kind     TEXT NOT NULL CHECK (kind IN ('kana', 'component', 'kanji', 'word')),
  track    TEXT NOT NULL DEFAULT 'main' CHECK (track IN ('kana', 'main'))
);

-- An item unlocks once every item it requires is learned.
CREATE TABLE path_requirements (
  item_key     TEXT NOT NULL REFERENCES path(item_key),
  requires_key TEXT NOT NULL REFERENCES path(item_key),
  PRIMARY KEY (item_key, requires_key)
);
